import{_ as a,c as s,a as i,aS as e}from"./chunks/framework.BB9D2qGO.js";const n="/assets/umami01.YMs96L3m.png",l="/assets/umami02.CCcT51Qy.png",t="/assets/umami03.2QQ8_eu_.png",p="/assets/umami04.CANLc7of.png",r="/assets/umami05.CYsMh97p.png",m="/assets/umami06.CygBG7V4.png",f=JSON.parse('{"title":"umami流量监控","description":"","frontmatter":{},"headers":[],"relativePath":"note/efficiency/operations/umami流量监控.md","filePath":"note/efficiency/operations/umami流量监控.md","lastUpdated":1753880156000}'),h={name:"note/efficiency/operations/umami流量监控.md"},o=e(`<h1 id="umami流量监控" tabindex="-1">umami流量监控 <a class="header-anchor" href="#umami流量监控" aria-label="Permalink to &quot;umami流量监控&quot;">​</a></h1><p>sealos一键部署：<a href="https://zhuanlan.zhihu.com/p/649380136" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/649380136</a></p><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Umami 是 是谷歌分析的一个简单、快速、注重隐私的替代品。</p><p>官方网站：<a href="https://umami.is/" target="_blank" rel="noreferrer">https://umami.is/</a></p><p>官方文档：<a href="https://umami.is/docs/" target="_blank" rel="noreferrer">https://umami.is/docs/</a></p><p>开源地址：<a href="https://github.com/umami-software/umami" target="_blank" rel="noreferrer">https://github.com/umami-software/umami</a></p><p>演示地址： <a href="https://app.umami.is/share/8rmHaheU/umami.is" target="_blank" rel="noreferrer">https://app.umami.is/share/8rmHaheU/umami.is</a></p><p><strong>优点</strong></p><ul><li>简单分析 Umami 只测量你关心的重要指标：网页浏览量、使用的设备以及访问者的来源。这些数据都在一个易于浏览的页面上展示。</li><li>不限网站数量 Umami 通过一次安装就可以跟踪无限数量的网站，甚至还可以跟踪子域名和单个的 URL。</li><li>绕过广告拦截器 Umami 由你在自己进行托管部署，所以你可以有效地避免 Google Analytics 不同的广告拦截器。</li><li>轻量级 追踪脚本很小（只有 2KB），而且支持 IE 等旧版浏览器。</li><li>多账户 Umami 可用于为朋友或客户托管数据，只需创建一个单独的账号，他们就可以开始在自己的仪表板上跟踪自己的网站。</li><li>共享数据 如果你想公开分享你的统计数据，那么你可以使用一个唯一生成的 URL 进行共享。</li><li>移动端友好 Umami 界面已针对移动设备进行了优化，因此你可以从任何地方查看你的统计数据。</li><li>数据所有权 由于 Umami 是自托管的，因此你拥有所有数据。无需将你的数据交给第三方进行利用。</li><li>注重隐私 Umami 不收集任何个人身份信息，并对收集的所有数据进行匿名处理。</li><li>开源 Umami 是开源的，并采用 MIT 的开源协议</li></ul><p><strong>支持多种数据库：</strong></p><ul><li>默认推荐 PostgreSQL（性能更优）。</li><li>也兼容 MySQL/MariaDB。</li><li>还支持 SQLite（适合轻量级使用）。</li></ul><h2 id="本地安装" tabindex="-1">本地安装 <a class="header-anchor" href="#本地安装" aria-label="Permalink to &quot;本地安装&quot;">​</a></h2><p>其实仓库的README.md文件有部署步骤。很简单</p><p>第一步，拉取代码</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆仓库,拉取代码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/umami-software/umami.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> umami</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第二步，在根目录创建<code>.env</code>文件，</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">## DATABASE_URL=mysql://用户名:密码@IP:端口/数据库名称</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql://root:123456@localhost:3306/umami</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>第三步，编译代码，直接就链接数据库自动创建表了，很方便</p><p>测试用的</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编译打包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 本地启动，</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>实际生产环境用的，注意，一定要注意顺序，先build再start，build会初始化数据库，还会在根目录生成<code>.next</code>文件夹，中间会下载地理数据文件<code>GeoLite2-City.mmdb</code>，会很耗时， 需要等待一会才行。大概58M大小</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编译打包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动应用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>初始登录账号密码为 <code>admin</code> 和 <code>umami</code>，登录后可以在设置中修改</p><p>默认是英文的，但是可以设置为中文显示！！！</p><p>进去之后创建web网站，然后复制跟踪代码到自己的网站就可以了，很简单。</p><p><img src="`+n+'" alt="umami01"></p><h2 id="vercel部署" tabindex="-1">Vercel部署 <a class="header-anchor" href="#vercel部署" aria-label="Permalink to &quot;Vercel部署&quot;">​</a></h2><p>详细介绍如何在 Vercel 上免费部署 umami，并且使用 Vercel 创建一个免费的数据库。</p><h3 id="_1-在-github-fork-umami-项目" tabindex="-1">1. 在 Github Fork umami 项目 <a class="header-anchor" href="#_1-在-github-fork-umami-项目" aria-label="Permalink to &quot;1. 在 Github Fork umami 项目&quot;">​</a></h3><p>fork <a href="https://github.com/umami-software/umami" target="_blank" rel="noreferrer">https://github.com/umami-software/umami</a> 到自己的 github 账号</p><h3 id="_2-在-vercel-导入-umami-项目" tabindex="-1">2. 在 Vercel 导入 umami 项目 <a class="header-anchor" href="#_2-在-vercel-导入-umami-项目" aria-label="Permalink to &quot;2. 在 Vercel 导入 umami 项目&quot;">​</a></h3><p>打开 <a href="https://vercel.com" target="_blank" rel="noreferrer">https://vercel.com</a>，如果没有账号需要先注册，来到 Overview 面板，点击 Add New，选择 Project</p><p>选择刚刚 fork 的 umami 项目，点击 Import</p><p><img src="'+l+'" alt="umami01"></p><p>进入 New Project 页面，Environment Variables 是必需的，需要添加 DATABASE_URL，这些值在项目初始安装中会被用来作为 umami 配置。先空着不填，稍后我们会同样使用 Vercel 创建一个免费的数据库。</p><p>此处直接点击 Deploy 部署即可，由于没有提供环境变量，Vercel 会提示部署失败。</p><p><img src="'+t+'" alt="umami01"></p><h3 id="_3-在-vercel-创建-neon-数据库并关联" tabindex="-1">3. 在 Vercel 创建 Neon 数据库并关联 <a class="header-anchor" href="#_3-在-vercel-创建-neon-数据库并关联" aria-label="Permalink to &quot;3. 在 Vercel 创建 Neon 数据库并关联&quot;">​</a></h3><p>切换到 Storage 面板，点击 Create Database，umami 官方文档要求使用 PostgreSQL，所以此处我们选择 Neon 。</p><p><img src="'+p+'" alt="umami01"></p><p><img src="'+r+'" alt="umami01"></p><p>创建成功后，进入数据库页面，点击 Connect Project</p><p><img src="'+m+'" alt="umami01"></p><h3 id="_4-重新部署-umami-项目" tabindex="-1">4. 重新部署 umami 项目 <a class="header-anchor" href="#_4-重新部署-umami-项目" aria-label="Permalink to &quot;4. 重新部署 umami 项目&quot;">​</a></h3><p>连接好数据库后，就可以重新部署了，点击 umami 项目，进入 Deployments 面板，找到刚才部署失败的 deployment，点击 Redeploy 重新部署，成功部署大约需要几分钟时间。</p><p>部署成功后，登录 umami 后台。初始账号密码：</p><p>UserName: admin Password: umami</p>',48),c=[o];function u(d,k,b,g,_,F){return i(),s("div",null,c)}const v=a(h,[["render",u]]);export{f as __pageData,v as default};
